    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 85-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm isolated humeral head osteonecrosis with preserved glenoid cartilage. Which of the following is the most appropriate surgical intervention?', '["Arthrodesis", "Hemiarthroplasty", "Arthroscopic debridement and subacromial decompression", "Reverse Total Shoulder Arthroplasty (rTSA)", "Anatomic Total Shoulder Arthroplasty (TSA)"]'::jsonb, 1, 'The primary indication for Hemiarthroplasty is isolated humeral head osteonecrosis with preserved glenoid cartilage. Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
    (v_topic_id, 'A 75-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Well below the stem tip. This is classified as Vancouver C. What is the most appropriate management?', '["ORIF with plate fixation", "Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement", "Nonoperative management with protected weight-bearing", "ORIF with plates and cables"]'::jsonb, 0, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver C fractures occur Well below the stem tip and are best managed by ORIF with plate fixation.'),
    (v_topic_id, 'A 60-year-old patient with medial knee pain is being considered for a unicompartmental knee arthroplasty (UKA). Which of the following findings would be a contraindication for UKA in this patient?', '["Body mass index of 28", "Isolated medial compartment osteoarthritis", "Correctable varus deformity", "Intact Anterior Cruciate Ligament (ACL)", "Inflammatory arthritis (e.g., Rheumatoid arthritis)"]'::jsonb, 4, 'Inflammatory arthritis (e.g., Rheumatoid arthritis) is a recognized contraindication to Unicompartmental Knee Arthroplasty (UKA). Patients with these features should typically undergo Total Knee Arthroplasty (TKA) instead, as UKA relies on the presence of an intact ACL and relative sparing of the other knee compartments.'),
    (v_topic_id, 'A 74-year-old patient presents with increasing pain in the hip 3 weeks after a total hip arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Cutibacterium acnes; One-stage exchange arthroplasty", "Staphylococcus aureus; Debridement, antibiotics, and implant retention (DAIR)", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Staphylococcus aureus; Two-stage exchange arthroplasty"]'::jsonb, 2, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus aureus and can sometimes be managed with Debridement, antibiotics, and implant retention (DAIR). Chronic infections are usually due to less virulent organisms like Staph epidermidis and require a two-stage exchange.'),
    (v_topic_id, 'A 72-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["A patient with severe avascular necrosis of the talus", "A patient with a history of deep soft-tissue infection in the affected ankle", "A young, high-demand laborer with a physically strenuous job", "An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A patient with marked, uncorrectable varus deformity of the hindfoot"]'::jsonb, 3, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 58-year-old patient presents with a painful right hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Iliopsoas bursitis", "Periprosthetic joint infection", "Adverse local tissue reaction (ALTR) / Pseudotumor", "Aseptic loosening due to polyethylene wear", "Heterotopic ossification"]'::jsonb, 2, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 87-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose with poor bone stock. This is classified as Vancouver B3. What is the most appropriate management?', '["ORIF with plates and cables", "Revision arthroplasty with a longer stem", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "ORIF with intramedullary nailing"]'::jsonb, 3, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B3 fractures occur Around the stem, stem is loose with poor bone stock and are best managed by Revision arthroplasty with proximal femoral replacement.'),
    (v_topic_id, 'A 67-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Cutibacterium acnes", "Streptococcus pyogenes", "Staphylococcus epidermidis", "Staphylococcus aureus", "Pseudomonas aeruginosa"]'::jsonb, 0, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 81-year-old female undergoes a total hip arthroplasty via a standard anterolateral approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Flexion, abduction, and external rotation", "Extension and internal rotation", "Extension and external rotation", "Extension, abduction, and internal rotation", "Flexion, adduction, and external rotation"]'::jsonb, 2, 'In a anterolateral approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Superior gluteal nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 60-year-old male with a history of ankylosing spondylitis undergoes a total hip arthroplasty. He is at high risk for developing postoperative heterotopic ossification. Which of the following is an effective prophylactic measure?', '["Prolonged immobilization in a spica cast", "Intravenous bisphosphonates immediately post-op", "Postoperative prophylactic enoxaparin", "Postoperative indomethacin or single-dose radiation therapy", "High-dose systemic corticosteroids for 2 weeks"]'::jsonb, 3, 'Heterotopic ossification is a common complication after THA, especially in patients with a history of it, ankylosing spondylitis, or hypertrophic osteoarthritis. Prophylaxis typically involves a course of oral NSAIDs (like indomethacin) or a single fraction of localized radiation therapy.'),
    (v_topic_id, 'A 90-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement", "Nonoperative or cerclage wires if widely displaced", "ORIF with plates and cables", "Nonoperative management with protected weight-bearing"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
    (v_topic_id, 'A 59-year-old patient is 8 weeks out from a primary total knee arthroplasty and complains of severe stiffness. Range of motion is 10 to 70 degrees. After failing aggressive physical therapy, what is the next most appropriate step in management?', '["Revision total knee arthroplasty", "Open arthrolysis and synovectomy", "Arthroscopic lysis of adhesions", "Long-term casting in extension", "Manipulation under anesthesia (MUA)"]'::jsonb, 4, 'Stiffness or arthrofibrosis after TKA is a frustrating complication. If aggressive physical therapy fails, the most appropriate next step within the first 2-3 months is typically a manipulation under anesthesia (MUA) to break up intra-articular adhesions and improve range of motion.'),
    (v_topic_id, 'A 90-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is loose with poor bone stock. This is classified as Vancouver B3. What is the most appropriate management?', '["Nonoperative management with protected weight-bearing", "ORIF with plates and cables", "Revision arthroplasty with proximal femoral replacement", "ORIF with intramedullary nailing", "Revision arthroplasty with a longer stem"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B3 fractures occur Around the stem, stem is loose with poor bone stock and are best managed by Revision arthroplasty with proximal femoral replacement.'),
    (v_topic_id, 'A 82-year-old patient presents with increasing pain in the shoulder 8 months after a total shoulder arthroplasty. Aspiration yields purulent fluid. What is the most likely responsible organism and the standard surgical management?', '["Staphylococcus epidermidis (Coagulase-negative Staph); Two-stage exchange arthroplasty", "Staphylococcus epidermidis; Debridement, antibiotics, and implant retention (DAIR)", "Cutibacterium acnes; One-stage exchange arthroplasty", "Streptococcus pyogenes; Suppressive intravenous antibiotics only", "Staphylococcus aureus; Two-stage exchange arthroplasty"]'::jsonb, 0, 'Periprosthetic joint infections present differently based on timing. Acute infections (typically < 3-4 weeks) are often caused by highly virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and can sometimes be managed with Two-stage exchange arthroplasty. Chronic infections are usually due to less virulent organisms like Staphylococcus epidermidis (Coagulase-negative Staph) and require a two-stage exchange.'),
    (v_topic_id, 'A 80-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding urinary tract infection, which of the following is most accurate in this setting?', '["Associated with prolonged indwelling catheterization", "It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics", "It is a rare complication seen almost exclusively in young patients"]'::jsonb, 0, 'Urinary tract infection is a known systemic complication following major joint arthroplasty. Specifically, it is associated with prolonged indwelling catheterization. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 71-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A patient with a history of deep soft-tissue infection in the affected ankle", "A patient with marked, uncorrectable varus deformity of the hindfoot", "A young, high-demand laborer with a physically strenuous job", "A patient with severe avascular necrosis of the talus"]'::jsonb, 0, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 72-year-old female undergoes a total hip arthroplasty via a standard anterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension and internal rotation", "Extension, abduction, and internal rotation", "Extension and external rotation", "Flexion, abduction, and external rotation", "Flexion, adduction, and external rotation"]'::jsonb, 2, 'In a anterior approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Lateral femoral cutaneous nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 87-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Well below the stem tip. This is classified as Vancouver C. What is the most appropriate management?', '["Revision arthroplasty with proximal femoral replacement", "ORIF with plate fixation", "ORIF with plates and cables", "Revision arthroplasty with a longer stem", "Nonoperative management with protected weight-bearing"]'::jsonb, 1, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver C fractures occur Well below the stem tip and are best managed by ORIF with plate fixation.'),
    (v_topic_id, 'A 90-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding urinary tract infection, which of the following is most accurate in this setting?', '["It is solely caused by the type of implant bearing surface used", "It only occurs after the 3-month postoperative mark", "It is completely preventable with prophylactic antibiotics", "It is a rare complication seen almost exclusively in young patients", "Associated with prolonged indwelling catheterization"]'::jsonb, 4, 'Urinary tract infection is a known systemic complication following major joint arthroplasty. Specifically, it is associated with prolonged indwelling catheterization. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 82-year-old patient presents with a painful left hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Iliopsoas bursitis", "Aseptic loosening due to polyethylene wear", "Periprosthetic joint infection", "Heterotopic ossification", "Adverse local tissue reaction (ALTR) / Pseudotumor"]'::jsonb, 4, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
    (v_topic_id, 'A 72-year-old female undergoes a total hip arthroplasty via a standard anterolateral approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension and internal rotation", "Flexion, adduction, and external rotation", "Extension and external rotation", "Flexion, abduction, and external rotation", "Extension, abduction, and internal rotation"]'::jsonb, 2, 'In a anterolateral approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Superior gluteal nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 66-year-old patient complains of a ''limp'' 6 weeks after a primary total hip arthroplasty. On examination, the operative leg appears longer. What is a common intraoperative cause for lengthening the operative leg during THA?', '["Using a smaller femoral head size", "Placing the femoral component in varus", "Maximizing soft tissue tension to prevent dislocation", "Aggressive reaming of the acetabulum", "Excessive resection of the femoral neck"]'::jsonb, 2, 'Leg length discrepancy is a common patient complaint after THA. Surgeons sometimes intentionally or unintentionally lengthen the leg to increase myofascial tension (especially of the abductors) to improve hip stability and decrease the risk of dislocation.'),
    (v_topic_id, 'A 74-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding myocardial infarction, which of the following is most accurate in this setting?', '["It is completely preventable with prophylactic antibiotics", "It is solely caused by the type of implant bearing surface used", "It is a rare complication seen almost exclusively in young patients", "Within the first 30 days postoperatively", "It only occurs after the 3-month postoperative mark"]'::jsonb, 3, 'Myocardial infarction is a known systemic complication following major joint arthroplasty. Specifically, it is within the first 30 days postoperatively. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 86-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Around the stem, stem is well-fixed. This is classified as Vancouver B1. What is the most appropriate management?', '["Revision arthroplasty with a longer stem", "ORIF with intramedullary nailing", "Nonoperative management with protected weight-bearing", "Revision arthroplasty with proximal femoral replacement", "ORIF with plates and cables"]'::jsonb, 4, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver B1 fractures occur Around the stem, stem is well-fixed and are best managed by ORIF with plates and cables.'),
    (v_topic_id, 'A 66-year-old patient with end-stage post-traumatic ankle osteoarthritis is seeking surgical intervention. Which of the following patient profiles is considered the MOST ideal candidate for a total ankle arthroplasty (TAA) rather than an ankle arthrodesis?', '["An older, lower-demand patient with relatively good bone stock and normal hindfoot alignment", "A young, high-demand laborer with a physically strenuous job", "A patient with severe avascular necrosis of the talus", "A patient with marked, uncorrectable varus deformity of the hindfoot", "A patient with a history of deep soft-tissue infection in the affected ankle"]'::jsonb, 0, 'Total ankle arthroplasty is generally preferred for older, lower-demand individuals who wish to preserve range of motion. Contraindications typically include high physical demand, severe malalignment, prior infection, and poor bone stock (e.g., extensive AVN of the talus). Arthodesis remains the gold standard for high-demand patients.'),
    (v_topic_id, 'A 85-year-old sustains a fall and suffers a periprosthetic femur fracture around their total hip arthroplasty. Radiographs show the fracture is Trochanteric region. This is classified as Vancouver A. What is the most appropriate management?', '["Revision arthroplasty with a longer stem", "Revision arthroplasty with proximal femoral replacement", "Nonoperative or cerclage wires if widely displaced", "Nonoperative management with protected weight-bearing", "ORIF with plates and cables"]'::jsonb, 2, 'The Vancouver classification dictates treatment of postoperative periprosthetic femur fractures. Vancouver A fractures occur Trochanteric region and are best managed by Nonoperative or cerclage wires if widely displaced.'),
    (v_topic_id, 'A 72-year-old male undergoes a total hip arthroplasty via a standard posterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Flexion, adduction, and internal rotation", "Extension and internal rotation", "Flexion, abduction, and external rotation", "Flexion, adduction, and external rotation", "Extension, abduction, and internal rotation"]'::jsonb, 0, 'In a posterior approach to the hip, the typical position of instability causing dislocation is flexion, adduction, and internal rotation. The Sciatic nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 55-year-old patient presents with vague, progressive shoulder pain 1 year after an anatomic total shoulder arthroplasty. Inflammatory markers are minimally elevated, and there is no frank purulence on aspiration. Intraoperative cultures eventually grow a slow-growing anaerobic Gram-positive bacillus. Which organism is most likely responsible?', '["Staphylococcus epidermidis", "Staphylococcus aureus", "Cutibacterium acnes", "Streptococcus pyogenes", "Pseudomonas aeruginosa"]'::jsonb, 2, 'Cutibacterium (formerly Propionibacterium) acnes is a common skin flora around the shoulder and a frequent cause of indolent, chronic periprosthetic joint infections following shoulder arthroplasty. It often requires prolonged incubation (up to 14 days) to grow in culture.'),
    (v_topic_id, 'A 79-year-old patient undergoes a total hip arthroplasty via an anterior approach. Postoperatively, the patient has profound weakness in knee extension and decreased sensation over the anterior thigh. Which structure was most likely injured during the procedure?', '["Sciatic nerve", "Obturator nerve", "Lateral femoral cutaneous nerve", "Femoral nerve", "Superior gluteal nerve"]'::jsonb, 3, 'The femoral nerve provides motor innervation to the quadriceps (knee extension) and sensory innervation to the anterior thigh. It can be injured during an anterior approach to the hip due to retractor placement over the anterior rim of the acetabulum.'),
    (v_topic_id, 'A 65-year-old female undergoes a total hip arthroplasty via a standard anterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Extension and external rotation", "Extension and internal rotation", "Flexion, abduction, and external rotation", "Flexion, adduction, and external rotation", "Extension, abduction, and internal rotation"]'::jsonb, 0, 'In a anterior approach to the hip, the typical position of instability causing dislocation is extension and external rotation. The Lateral femoral cutaneous nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 80-year-old patient is recovering from a total hip arthroplasty. According to current guidelines for patients at standard risk for deep vein thrombosis (DVT), what is the most appropriate duration for pharmacologic VTE prophylaxis?', '["3 months", "3 to 5 days", "6 months", "At least 10 to 14 days, up to 35 days", "24 to 48 hours"]'::jsonb, 3, 'Current orthopedic guidelines recommend extending pharmacologic venous thromboembolism (VTE) prophylaxis for a minimum of 10 to 14 days, and up to 35 days, following major joint replacement surgery (THA or TKA) to minimize the risk of DVT and pulmonary embolism.'),
    (v_topic_id, 'A 65-year-old female undergoes a total hip arthroplasty via a standard posterior approach. Postoperatively, the patient is at highest risk for dislocation if the hip is placed in which of the following positions?', '["Flexion, adduction, and internal rotation", "Extension and internal rotation", "Flexion, abduction, and external rotation", "Extension, abduction, and internal rotation", "Flexion, adduction, and external rotation"]'::jsonb, 0, 'In a posterior approach to the hip, the typical position of instability causing dislocation is flexion, adduction, and internal rotation. The Sciatic nerve is also at risk during this approach. Patients are routinely placed on specific hip precautions to avoid these extreme ranges of motion early in the postoperative period.'),
    (v_topic_id, 'A 74-year-old patient undergoes an anatomic total shoulder arthroplasty. During the deltopectoral approach, care must be taken to protect the nerve that innervates the deltoid and teres minor. Injury to this nerve most commonly occurs at which surgical step?', '["Biceps tenodesis", "Glenoid preparation", "Subscapularis tenotomy", "Inferior capsular release", "Humeral head resection"]'::jsonb, 3, 'The axillary nerve innervates the deltoid and teres minor. It travels close to the inferior capsule of the shoulder joint and is at greatest risk of injury during inferior capsular release in shoulder arthroplasty.'),
    (v_topic_id, 'A 71-year-old patient is undergoing a total joint arthroplasty. The surgical team is reviewing the risk of perioperative systemic complications. Regarding delirium, which of the following is most accurate in this setting?', '["It only occurs after the 3-month postoperative mark", "Common in elderly patients, associated with narcotic use and hypoxia", "It is solely caused by the type of implant bearing surface used", "It is a rare complication seen almost exclusively in young patients", "It is completely preventable with prophylactic antibiotics"]'::jsonb, 1, 'Delirium is a known systemic complication following major joint arthroplasty. Specifically, it is common in elderly patients, associated with narcotic use and hypoxia. Proper medical optimization and perioperative care are crucial for risk mitigation.'),
    (v_topic_id, 'A 76-year-old patient presents with severe shoulder pain and limited range of motion. Imaging and clinical evaluation confirm osteoarthritis with an intact rotator cuff. Which of the following is the most appropriate surgical intervention?', '["Arthrodesis", "Hemiarthroplasty", "Reverse Total Shoulder Arthroplasty (rTSA)", "Arthroscopic debridement and subacromial decompression", "Anatomic Total Shoulder Arthroplasty (TSA)"]'::jsonb, 4, 'The primary indication for Anatomic Total Shoulder Arthroplasty (TSA) is osteoarthritis with an intact rotator cuff. Anatomic TSA relies on an intact rotator cuff to maintain the humeral head centered on the glenoid. In contrast, rTSA is designed for cuffs that are severely deficient, utilizing the deltoid muscle to substitute for the rotator cuff.'),
    (v_topic_id, 'A 76-year-old patient presents with a painful left hip and a palpable soft-tissue mass. They underwent a metal-on-metal total hip arthroplasty 10 years ago. Serum cobalt and chromium levels are elevated. What is the most likely diagnosis?', '["Heterotopic ossification", "Aseptic loosening due to polyethylene wear", "Iliopsoas bursitis", "Adverse local tissue reaction (ALTR) / Pseudotumor", "Periprosthetic joint infection"]'::jsonb, 3, 'Metal-on-metal hip implants can produce metal ion wear debris, which can trigger an adverse local tissue reaction (ALTR), often manifesting as a solid or cystic pseudotumor, pain, and elevated serum metal ions.'),
